## 2B. Helper Functions --------------------------------------------------------

# Helper function that plots the pre gcam historical emissions against teh 
# GCAM emissions that drive hector post 2023. 
# Args 
#   hist_data: data frame of the pre gcam historical inputs
#   gcam_data: data frame of the GCAM emissions 
#   variables: vector of variable names 
#   write_to: str directory where to save the results to 
#   type: str that determines the figure file type that is being saved, default set to global option
#   w: int determines the width of the figure saved, default set to global option
#   h: int determines the height of the figure saved, default set to global option
# Returns: list of ggplot objects and write figures out to disk 
plot_emiss_transition <- function(hist_data, 
                                  gcam_data, 
                                  variables, 
                                  write_to, 
                                  type = TYPE, 
                                  w = WIDTH,
                                  h = HEIGHT){
  
  plots <- vector("list", length(variables)) # preallocate list
  for(v in variables){
    
    print(v)
    
    hist_data %>% 
      filter(variable == v) %>% 
      filter(year >= 1975) -> 
      hist_to_plot
    
    gcam_data %>% 
      filter(variable == v) %>% 
      filter(year <= 2050) -> 
      gcam_to_plot
    
    # Make the plot! 
    ggplot() + 
      geom_vline(xintercept = 2023, color = "grey") + 
      geom_line(data = hist_to_plot, aes(year, value, color = "pre-gcam hist.")) +
      geom_line(data = gcam_to_plot, aes(year, value, color = scenario), alpha = 0.25) + 
      geom_point(data = gcam_to_plot, aes(year, value, color = scenario)) + 
      labs(title = "Transition of historical to GCAM emissions", 
           subtitle = v, 
           y = getunits(v), 
           x = NULL, caption = "transition from historical to GCAM emissions in 2023") + 
      scale_color_manual(values = GCAM_COLOR_SCHEME) -> 
      p
    
    fname <- file.path(write_to, "transition", paste0("trans_", v, ".", type))
    ggsave(plot = p, filename = fname, width = w, height = h)
    
    plots[[v]] <- p
    
  }
  
  return(plots)
  
}

