## 4B. Helper Functions  --------------------------------------------------------

# Helper function that plots the inputs against one another 
# Args 
#   data: data frame of hector results 
#   variables: vector of variable names 
#   write_to: str directory where to save the results to 
#   tag: str indicating the scenario type or what not is being saved, a unique identifier
#   type: str that determines the figure file type that is being saved, default set to global option
#   w: int determines the width of the figure saved, default set to global option
#   h: int determines the height of the figure saved, default set to global option
# Returns: list of ggplot objects and write figures out to disk 
plot_hector_fxn <- function(data, variables, write_to, tag,
                            type = TYPE, w = WIDTH, h = HEIGHT){
  
  # Calculate the RMSE between the inputs... 
  data %>%
    # Subset the data so that it only includes the variables of interest 
    filter(variable %in% variables) %>% 
    distinct %>% 
    pivot_wider(names_from = version, values_from = value) %>%
    na.omit %>% 
    mutate(SE = (`V3.2.0` - V3.5.0)^2) %>% 
    summarise(RMSE = sqrt(mean(SE)), .by = c(variable, units, scenario)) %>%
    mutate(RMSE = signif(RMSE, digits = 3)) -> 
    RMSE_df
  
  
  # Make a list to save all the pots to 
  plots <- vector("list", length(variables)) # preallocate list
  
  # For each variable make a line plot and include a 
  for (v in variables){
    # v <- variables[1]
    print(v)
    
    # Subset the RMSE data frame 
    RMSE_df %>% 
      filter(variable == v) -> 
      RMSE_df_to_plot
    
    # subset and format the RMSE results to be included in the plot. 
    tibble(x = Inf, 
           y = -Inf, 
           label = list(RMSE_df_to_plot)) -> 
      RMSE_tib
    
    data %>%
      filter(variable == v) -> 
      to_plot 
    
    ggplot() +
      geom_line(data = to_plot,
                aes(year, value, color = version, linetype = version, 
                    group = interaction(scenario, version))) +
      labs(x = NULL, title = "Stand Alone Hector Comparison",
           subtitle = v,
           y = RMSE_df_to_plot$units[1]) +
      theme(legend.title = element_blank(),
            legend.position = "bottom") +
      scale_color_manual(values = COLOR_SCHEME) -> 
      p1
    
    # RMSE table
    ggplot() +
      geom_table(
        data = RMSE_tib,
        aes(x = 0, y = 1, label = label),
        hjust = 0,
        vjust = 1
      ) +
      xlim(0, 1) +
      ylim(0, 1) +
      theme_void() +
      theme(
        plot.margin = margin(0, 0, 0, 0)
      ) + 
      coord_cartesian(clip = "off") -> 
      p2
    
    
    p1 | p2 +
      plot_layout(widths = c(1, 0.15)) -> 
      p
    
    fname <- file.path(write_to, "hector", paste0("hector_", tag, "_", v, ".", type))
    ggsave(plot = p, filename = fname, width = w, height = h)
    
    plots[[v]] <- p
  }
  
  return(plots)
  
}


