## 6A. Load Data  ---------------------------------------------------------------
# Import the hector results that will be compared with the AR6 benchmarks values. 
data.frame(rslts = list.files(here("data"), pattern = "v32|v35", full.names = TRUE)) %>% 
  filter(grepl(pattern = "AR6", x = rslts)) %>% 
  pull(rslts) %>% 
  lapply(read.csv) %>% 
  bind_rows %>% 
  distinct %>% 
  mutate(version = paste0("V", version)) -> 
  hector_rslts

# Load the benchmarking data, there are two different versions of the AR6 data 
# the assessed ranges and then also the individual SCMs. 
here("data", "auxiliary") %>% 
  list.files("ar6_scms.csv", full.names = TRUE) %>% 
  read.csv() -> 
  ar6_scm_benchmarks

here("data", "auxiliary") %>% 
  list.files("ar6.csv", full.names = TRUE) %>% 
  read.csv() -> 
  ar6_ipcc_benchmarks

# Plot aesthetics 
JW <- 0.15
COLORS.BENCHMARKS <- c(COLOR_SCHEME ,"ipcc ar6" = "black", "scms from ar6" = "grey", 
                       "FaIRv1.6.2" = "blue", "MAGICC7" = "purple")


## 6B. Emergent Metrics  -------------------------------------------------------

# Key metrics to compare 
